    switch (this.type) {
      case 2:
        str += "emitter:" + this.proton.emitters.length + "<br>";
        if (emitter) str += "em speed:" + emitter.emitSpeed + "<br>";
        if (emitter) str += "pos:" + this.getEmitterPos(emitter);
